static inline int play_fp_carbine_find(const char *name)
{
    int i;
    for (i = 0; i < PLAY_FP_CARBINE_NODES; i++)
        if (strcmp(PLAY_FP_CARBINE_NODE[i].name, name) == 0) return i;
    return -1;
}
static inline const float *play_fp_carbine_node_quat(int node, int frame)
{
    const play_fp_carbine_node *n = &PLAY_FP_CARBINE_NODE[node];
    unsigned f = n->q_n > 1 ? (unsigned)frame % PLAY_FP_CARBINE_FRAMES : 0u;
    return &PLAY_FP_CARBINE_Q[(n->q_at + f) * 4];
}
static inline const float *play_fp_carbine_node_trans(int node, int frame)
{
    const play_fp_carbine_node *n = &PLAY_FP_CARBINE_NODE[node];
    unsigned f = n->t_n > 1 ? (unsigned)frame % PLAY_FP_CARBINE_FRAMES : 0u;
    return &PLAY_FP_CARBINE_T[(n->t_at + f) * 3];
}
